$(document).ready(function(){$('[data-toggle="popover"]').popover();$(".elx-multi-select").select2({columns:2,search:true,selectAll:true,texts:{placeholder:"Select one or more Roles"}});$.ajax({url:"/autocomplete_institutes"}).done(function(data){$(".elx-autocomp-institution").autocomplete({source:data,minLength:3})})});
